def focus_layout(
    mod_root: Path,
    focus_index: Optional[FocusIndex] = None,
    *,
    tag: Optional[str] = None,
    file: Optional[str] = None,
    vanilla_path: Optional[Path] = None,
    include_positions: bool = False,
    limit: int = 300,
