from pathlib import Path
from tempfile import TemporaryDirectory
from md_mcp.analysis.focus_graph import focus_graph
from md_mcp.indexes.focus import FocusIndex

body = '''focus_tree = {
  focus = { id = TST_C x = 0 y = 0 cost = 100 }
  focus = { id = TST_A x = 0 y = 1 cost = 60 }
  focus = { id = TST_B x = 0 y = 2 cost = 60 }
  focus = { id = TST_D x = 0 y = 3 cost = 1 prerequisite = { focus = TST_C } }
  focus = { id = TST_E x = 0 y = 4 cost = 1 prerequisite = { focus = TST_C } }
  focus = {
    id = TST_target
    x = 0 y = 5 cost = 1
    prerequisite = { focus = TST_A focus = TST_D }
    prerequisite = { focus = TST_B focus = TST_E }
  }
}
'''
with TemporaryDirectory() as td:
    root = Path(td)
    (root/'tools'/'validation').mkdir(parents=True)
    (root/'descriptor.mod').write_text('x', encoding='utf-8')
    d = root/'common'/'national_focus'
    d.mkdir(parents=True)
    (d/'t.txt').write_text(body, encoding='utf-8')
    fi = FocusIndex(root, root/'.cache')
    out = focus_graph('TST', root, fi, detail='paths', focus_ids=['TST_target'])
    print(out['paths'][0])
PY

